INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (1, 'lamborghini-murcielago-6-2-v12', 'Lamborghini Murciélago 6.2 V12 Coupé', 'Lamborghini', 'Murciélago', 2003, 34800, 580, 426, 6192, '6,2 l V12-Saugmotor (60° Bankwinkel)', 'Automatik / E-Gear', 'Permanenter Allradantrieb (VT)', 'Benzin', 'Nero Aldebaran Metallic', 'Vollleder Nero Perseus / Kontrastnaht', NULL, 1, 0, 'available', 1, 'Der Lamborghini Murciélago der frühen 2000er – ein zeitloser V12-Supersportwagen mit dem letzten klassischen Bizzarrini-Zwölfzylinderblock.', 'Der Lamborghini Murciélago markiert den Beginn einer neuen Ära in Sant’Agata Bolognese unter der Designsprache von Luc Donckerwolke – und bewahrt zugleich die ungefilterte Seele des klassischen 6,2-Liter-V12-Saugmotors. Dieses gepflegte Exemplar aus der begehrten ersten Serie wurde in unserer Bonner Fachwerkstatt umfassend geprüft und dokumentiert. Scherentüren, variable Lufteinlässe (VACS) und eine kompromisslose Präsenz machen ihn zu einem wertstabilen Sammlerstück erster Güte.', '["Begehrte Erstserie (6,2-Liter-V12 mit 580 PS / 426 kW)","Umfassende technische Durchsicht & Diagnose durch Auto Kremer Bonn","Originales Bordbuch, Servicehistorie & Zweitschlüssel vorhanden","Variable Lufteinlässe (VACS) & klassische Lamborghini-Scherentüren","Differenzbesteuert gemäß § 25a UStG"]', 'https://suchen.mobile.de/fahrzeuge/details.html?id=432623451', 1, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (1, '/media/vehicles/murcielago-v12-1.avif', 'Lamborghini Murciélago 6.2 V12 Coupé Front-Seitenansicht im Showroom von Auto Kremer', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (1, '/media/vehicles/murcielago-v12-2.avif', 'Lamborghini Murciélago 6.2 V12 Detail- und Heckansicht', 1280, 854, 2);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (1, '/media/vehicles/murcielago-v12-3.avif', 'Lamborghini Murciélago 6.2 V12 Interieur und Cockpit', 1280, 854, 3);
INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (2, 'lamborghini-gallardo-5-0-handschalter', 'Lamborghini Gallardo 5.0 V10 Handschalter', 'Lamborghini', 'Gallardo Coupé', 2004, 41200, 500, 368, 4961, '5,0 l V10-Saugmotor (Even-Firing)', 'Handschaltung', 'Permanenter Allradantrieb', 'Benzin', 'Giallo Midas Perleffekt', 'Leder Nero / Gelbe Ziernähte', 13890000, 0, 0, 'available', 1, 'Lamborghini Gallardo 5.0 mit extrem seltener offener 6-Gang-Handschaltung – purer V10-Klang und unverfälschte Mechanik.', 'Der manuell geschaltete Lamborghini Gallardo 5.0 zählt weltweit zu den begehrtesten Varianten seiner Baureihe und steht sinnbildlich für die letzte Ära analoger Mittelmotor-Sportwagen aus Sant’Agata. Jedes Einrasten in der offenen Metall-Schaltkulisse verbindet den Fahrer unmittelbar mit dem hochdrehenden Fünfliter-Zehnzylinder. Ein authentisches Sammlerfahrzeug mit hohem Wertsteigerungspotenzial, geprüft durch unsere Lamborghini-Spezialisten.', '["Werkseitiges 6-Gang-Schaltgetriebe mit offener Aluminium-Schaltkulisse","Klassischer 5,0-Liter-V10-Saugmotor ohne Partikelfilter mit unvergleichlichem Klangbild","Scheckheftgepflegter Zustand inklusive Kupplungs- und Verschleißprotokoll","Aluminium-Spaceframe-Karosserie in ikonischem Giallo Midas","Verkauf im Kundenauftrag / Differenzbesteuert gemäß § 25a UStG"]', 'https://suchen.mobile.de/fahrzeuge/details.html?id=438968054', 2, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (2, '/media/vehicles/gallardo-manual-1.avif', 'Lamborghini Gallardo 5.0 V10 Handschalter Außenansicht', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (2, '/media/vehicles/gallardo-manual-2.avif', 'Lamborghini Gallardo 5.0 V10 Seitenlinie und Leichtmetallfelgen', 1280, 854, 2);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (2, '/media/vehicles/gallardo-manual-3.avif', 'Lamborghini Gallardo 5.0 V10 offene 6-Gang-Schaltkulisse im Innenraum', 1280, 854, 3);
INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (3, 'porsche-993-carrera-rs-clubsport-1995', 'Porsche 911 (993) Carrera RS Clubsport', 'Porsche', '993 Carrera RS Clubsport', 1995, 58400, 300, 221, 3746, '3,8 l 6-Zylinder-Boxermotor luftgekühlt (M64/20, VarioRam)', 'Handschaltung', 'Hinterradantrieb mit Sperrdifferenzial', 'Benzin', 'Indischrot / Speedgelb Akzent', 'Clubsport-Schalensitze Nomex Schwarz', NULL, 1, 0, 'available', 1, 'Originaler Porsche 993 RS Clubsport aus 1995 – deutsche Erstauslieferung, lückenlose Historie mit Büchern, Scheckheft und japanischer Dokumentation.', 'Als kompromisslose Homologationsversion für den internationalen GT-Sport stellt der Porsche 993 Carrera RS Clubsport (Werkscode M003) die Krönung der luftgekühlten 911-Historie dar. Dieses originale Exemplar aus dem Baujahr 1995 wurde erstmals in Deutschland ausgeliefert, später in eine renommierte japanische Sammlung exportiert und nun nach Deutschland re-importiert. Vollständige Bordmappe, Original-Scheckheft sowie sämtliche japanischen Wartungs- und Prüfberichte belegen die außergewöhnliche Authentizität.', '["Echter Werkscode M003 Clubsport mit eingeschweißtem Matter-Überrollkäfig","Deutsche Erstauslieferung (C00) aus 1995 mit vollständigem Scheckheft","Lückenlose Historie inkl. Bordbüchern und japanischen Inspektionsberichten","3,8-Liter-VarioRam-Saugmotor (M64/20) mit 6-Gang-Schaltgetriebe G50/31","Dreiteilige 18-Zoll-Speedline-for-Porsche-Leichtmetallräder & Aerokit-Heckflügel"]', 'https://suchen.mobile.de/fahrzeuge/details.html?id=431199459', 3, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (3, '/media/vehicles/porsche-993-rs-1.avif', 'Porsche 993 Carrera RS Clubsport (1995) Front- und Seitenansicht', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (3, '/media/vehicles/porsche-993-rs-2.avif', 'Porsche 993 Carrera RS Clubsport Heckflügel und Speedline-Felgen', 1280, 854, 2);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (3, '/media/vehicles/porsche-993-rs-3.avif', 'Porsche 993 Carrera RS Clubsport Innenraum mit Schalensitzen und Überrollkäfig', 1280, 854, 3);
INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (4, 'lamborghini-gallardo-spyder-5-0', 'Lamborghini Gallardo Spyder 5.0 V10', 'Lamborghini', 'Gallardo Spyder', 2007, 46900, 520, 382, 4961, '5,0 l V10-Saugmotor', 'Automatik / E-Gear', 'Permanenter Allradantrieb', 'Benzin', 'Nero Noctis', 'Bicolor Leder Nero / Giallo Taurus', 11490000, 0, 0, 'available', 0, 'Offenes V10-Supercar mit 520 PS, elektrohydraulischem Stoffverdeck, Allradantrieb und über 310 km/h Höchstgeschwindigkeit.', 'Zwischen 2006 und 2008 gefertigt, vereint der Lamborghini Gallardo Spyder 5.0 die keilförmige Linienführung des Centro Stile Lamborghini mit einem unmittelbaren Open-Air-Klangerlebnis. Mit gesteigerter Leistung von 520 PS, kürzer übersetztem Getriebe und versenkbarer Heckscheibe lässt sich die Symphonie des Zehnzylinders sowohl offen als auch geschlossen intensiv erleben. In unserer Bonner Werkstatt technisch aufbereitet und sofort einsatzbereit.', '["Leistungsgesteigerte 520-PS-Ausbaustufe mit kürzerer Getriebeübersetzung","Vollautomatisches Verdeck mit separat absenkbarer Glas-Heckscheibe","Vorderachs-Liftsystem & Rückfahrkamera","Frische Inspektion inkl. Flüssigkeits- und Diagnoseprotokoll bei Auto Kremer","Differenzbesteuert gemäß § 25a UStG"]', 'https://suchen.mobile.de/fahrzeuge/details.html?id=430841489', 4, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (4, '/media/vehicles/gallardo-spyder-1.avif', 'Lamborghini Gallardo Spyder 5.0 offen in der Seitenansicht', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (4, '/media/vehicles/gallardo-spyder-2.avif', 'Lamborghini Gallardo Spyder 5.0 Heckansicht und Vierrohr-Abgasanlage', 1280, 854, 2);
