INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (5, 'alfa-romeo-4c-2016', 'Alfa Romeo 4C Coupé Carbon-Monocoque', 'Alfa Romeo', '4C', 2016, 28500, 241, 177, 1742, '1,75 l 4-Zylinder-Turbomotor Vollaluminium', 'Automatik / E-Gear', 'Hinterradantrieb (Mittelmotor)', 'Benzin', 'Rosso Alfa / Sichtcarbon', 'Sportsitze Leder / Mikrofaser mit roter Naht', 6490000, 0, 0, 'available', 0, 'Italienische Leichtbaukunst in reinster Form: unter 900 kg Trockengewicht, Carbon-Monocoque aus Modena, nur zwei Vorbesitzer und lückenlos scheckheftgepflegt.', 'Als Hommage an den legendären Tipo 33 Stradale wird der Alfa Romeo 4C rund um ein nur 65 Kilogramm leichtes Kohlefaser-Monocoque aufgebaut – gefertigt in Modena. Ohne Servolenkung, mit einem Leistungsgewicht von unter 4 kg/PS und unmittelbarer Rückmeldung ist dieses Exemplar aus dem Modelljahr 2016 ein kompromissloses Fahrerauto für Puristen. Mit lediglich zwei Vorbesitzern und lückenloser Wartungshistorie.', '["Ultraleichtes Prepreg-Carbon-Monocoque (895 kg Trockengewicht)","Nur 2 Vorbesitzer & lückenlos scheckheftgepflegt","Alfa TCT 6-Gang-Doppelkupplungsgetriebe mit Schaltwippen & DNA-Fahrmodi inkl. Race","Puristische Direktlenkung ohne Servounterstützung für ungefiltertes Feedback","Traditionsmarke unseres Hauses seit unserer Gründung 1967"]', 'https://suchen.mobile.de/fahrzeuge/details.html?id=438772501', 5, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (5, '/media/vehicles/alfa-4c-1.avif', 'Alfa Romeo 4C Coupé (2016) Front-Seitenansicht', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (5, '/media/vehicles/alfa-4c-2.avif', 'Alfa Romeo 4C Coupé Seitenprofil und Lufteinlässe', 1280, 854, 2);
