INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (6, 'referenz-lamborghini-murcielago-giallo', 'Lamborghini Murciélago 6.2 V12 Erstserie', 'Lamborghini', 'Murciélago', 2002, 29400, 580, 426, 6192, '6,2 l V12-Saugmotor', 'Handschaltung', 'Permanenter Allradantrieb (VT)', 'Benzin', 'Giallo Orion Metallic', 'Leder Nero', NULL, 1, 0, 'sold', 0, 'Verkaufte Sammler-Referenz: Früher Murciélago 6.2 V12 in ikonischer Werkskonfiguration – vermittelt in eine europäische Privatsammlung.', 'Dieses herausragende Exemplar des frühen Lamborghini Murciélago wurde durch Auto Kremer technisch betreut, aufbereitet und erfolgreich an einen langjährigen Sammler übergeben. Als Referenz steht dieses Fahrzeug exemplarisch für unseren Anspruch bei Ankauf, technischer Revision und diskreter Vermittlung seltener Zwölfzylinder aus Sant’Agata.', '["Erfolgreich durch Auto Kremer Bonn in Sammlerhand vermittelt","Komplette große V12-Inspektion in unserer Fachwerkstatt vor Übergabe","Originale Erstserien-Spezifikation mit dokumentierter Historie"]', NULL, 10, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (6, '/media/vehicles/sold-murcielago-1.avif', 'Verkaufter Lamborghini Murciélago 6.2 V12 Referenzfahrzeug bei Auto Kremer', 1280, 854, 1);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (6, '/media/vehicles/sold-murcielago-2.avif', 'Lamborghini Murciélago Referenz Heck- und Seitenansicht', 1280, 854, 2);
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (6, '/media/vehicles/sold-murcielago-3.avif', 'Lamborghini Murciélago Referenz Detailansicht', 1280, 854, 3);
INSERT INTO vehicles (id, slug, title, brand, model, year, mileage_km, power_ps, power_kw, displacement_cc, engine_type, transmission, drivetrain, fuel_type, exterior_color, interior_color, price_cents, price_on_request, vat_deductible, status, featured, summary, description, highlights_json, mobile_de_url, sort_order, created_at, updated_at) VALUES (7, 'referenz-lamborghini-diablo-se30', 'Lamborghini Diablo SE30 (30th Anniversary Limited Edition)', 'Lamborghini', 'Diablo SE30', 1994, 21800, 525, 386, 5707, '5,7 l V12-Saugmotor mit Magnesium-Ansaugtrakt', 'Handschaltung', 'Hinterradantrieb', 'Benzin', 'Viola SE30 Metallic', 'Alcantara Blu / Carbon', NULL, 1, 0, 'sold', 0, 'Verkaufte Ikone: Eines von weltweit nur 150 gebauten Jubiläumsmodellen zum 30-jährigen Bestehen von Automobili Lamborghini.', 'Zum 30-jährigen Markenjubiläum präsentierte Lamborghini 1994 den kompromisslos erleichterten Diablo SE30 mit Hinterradantrieb, Magnesium-Komponenten, Carbon-Karosserieteilen und 525 PS. Als ehemaliger offizieller Vertragshändler („European Dealer of the Year 1995“) verbindet unser Haus eine tiefe Historie mit der Diablo-Baureihe. Dieses seltene Jubiläumsfahrzeug wurde durch Auto Kremer erfolgreich vermittelt.', '["Streng limitierte Sonderserie (1 von weltweit 150 Exemplaren)","Gewichtsreduzierte Leichtbau-Spezifikation mit reinem Hinterradantrieb","5,7-Liter-V12 mit 525 PS und offener 5-Gang-Schaltkulisse"]', NULL, 11, '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z');
INSERT INTO vehicle_images (vehicle_id, url, alt, width, height, sort_order) VALUES (7, '/media/vehicles/sold-diablo-se30-1.avif', 'Verkaufter Lamborghini Diablo SE30 Jubiläumsmodell bei Auto Kremer Bonn', 1280, 854, 1);
